SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百二十一", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cdbcdc30bc009005cdae849020ae9c421da992f5/content/books/zizhi-tongjian/vol-291/year-0954/part-06/sources/library/jiuwudaishi-121-first-fu-empress/source.txt", "note": "《旧五代史》卷一百二十一，段落 jiu-wudaishi-205deb4a7860-p002829；EPUB电子本，纸本及异文待核", "id": "eb3c57e5-de72-55bd-b15e-497dfab9fe76"}, {"title": "资治通鉴·后周纪二", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/cdbcdc30bc009005cdae849020ae9c421da992f5/content/books/zizhi-tongjian/vol-291/year-0954/part-06/sources/library/tongjian-291-954-april-submissions/source.txt", "note": "《资治通鉴》后周纪二，段落 zizhi-tongjian-a63549944a71-p003464；电子底本待考，分段待核", "id": "0307020b-364e-5d53-a7bd-9ef39a2aa879"}, {"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/6e8f22e0feef7c5c3f1d27117d6777d1c8c5b7e7/content/books/zizhi-tongjian/vol-291/year-0954/part-04/sources/library/jiuwudaishi-114-april-supply-954/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002709；EPUB电子本，纸本及异文待核", "id": "92b8127e-0098-5570-8c7d-6980ff4ebbef"}, {"title": "新五代史·卷12·周本纪第十二·柴荣即位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/xinwudaishi-12-chairong-accession/source.txt", "note": "《新五代史》卷12·周本纪第十二·柴荣即位，段落 xin-wudaishi-b08f244b9241-p000376；已核上下文及传主，纸本及异文待核。", "id": "e8e8d8ba-d759-5bf8-896c-ca674bd3a93d"}, {"title": "旧五代史·卷109·李守贞传·河中陷落", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/69dcf8a2fbba2850268b5fe5a8e94410a672cacd/content/books/zizhi-tongjian/vol-288/year-0949/part-02/sources/library/jiuwudaishi-109-li-shouzhen-death/source.txt", "note": "《旧五代史》卷109·李守贞传·河中陷落，段落 jiu-wudaishi-205deb4a7860-p002625；已核上下文及传主，纸本及异文待核。", "id": "4e5f0ea3-2d7f-52f6-aa38-3d9f7f89943c"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "韩光愿", "aliases": ["韓光願"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，北汉宪州刺史。954年四月符彦卿奏报他与岚州刺史郭言均举城向后周投降。生卒年未载。", "biography": null, "status": "draft", "id": "8abac490-6609-5b51-9d45-a9d248c4ea47"}, {"name": "郭言（北汉岚州刺史）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉岚州刺史。954年四月举城向后周投降，由符彦卿奏报。与朱全忠属将、893年战死的晚唐郭言不同，分别建档。生卒年未载。", "biography": null, "status": "draft", "id": "e48d35e9-3628-52c3-8879-18d531f19c13"}, {"name": "符氏（柴荣宣懿皇后）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "符彦卿之女、符存审之孙女，先嫁李守贞之子李崇训。河中城陷时躲过丈夫的杀害，郭威将她送回父亲处；后嫁柴荣，954年四月被立为皇后。与柴荣后来所立符氏皇后区分；生卒年待后续相应史料校核。", "biography": null, "status": "draft", "id": "5fc1e8cd-d993-547b-a735-fe29fb2346df"}, {"name": "李守贞", "aliases": ["李守貞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋内客省使。940年五月受命担任马全节讨伐李金全军队的都监，职务由《旧五代史》本纪补充。生卒年未据本段确定。", "biography": null, "status": "draft", "id": "a3d16959-684f-5c82-b848-8dcbdc73e85a"}, {"name": "李崇训", "aliases": ["李崇訓"], "era": "五代十国", "birth_year": null, "death_year": 949, "description": "李守贞之子，符氏的前夫。《通鉴》及《旧五代史》符后传记他在河中城陷时杀弟妹，寻找妻子未果后自杀。与949年自焚名单中的李崇勋姓名和死法有差异，同人关系未证，暂不合并。", "biography": null, "status": "draft", "id": "13e5a2e8-a719-5faa-bdd6-90eab363bf08"}, {"name": "郭威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：郭威。", "biography": null, "status": "draft", "id": "3fe84db3-aa25-5be9-9dd3-8b46e28213af"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "符存审", "aliases": ["李存审", "符存"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：符存审。", "biography": null, "status": "draft", "id": "5cb2699c-0840-5cde-b42a-ad5f2eef0a71"}, {"name": "王彦超", "aliases": ["王彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "临清人，后晋护圣指挥使。946年六月受命与白延遇带所属十营兵赴邢州。生卒年未载。", "biography": null, "status": "draft", "id": "c981d4c7-7693-5ee8-a667-6ab1fccba981"}, {"name": "韩通", "aliases": ["韓通"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周保义军留后。954年正月正式任保义节度使，《旧五代史》以陕州留后称其前职。生卒年暂未核定。", "biography": null, "status": "draft", "id": "81e4d74c-3057-59e4-a9a3-5baa18bff059"}, {"name": "安彦进", "aliases": ["安彥進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉石州刺史。954年四月后周王彦超、韩通攻克石州时被俘。生卒年未载。", "biography": null, "status": "draft", "id": "87995e29-8100-564c-8223-9214514aced7"}, {"name": "李廷诲", "aliases": ["李廷誨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉沁州刺史。954年四月癸亥举城归降后周。生卒年未载。", "biography": null, "status": "draft", "id": "725f0241-0a61-5131-b7ca-659ffc64c4da"}, {"name": "李勍", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉忻州监军。954年四月癸酉杀死刺史赵皋及契丹通事杨耨姑，以城归降后周，获任忻州刺史。生卒年未载。", "biography": null, "status": "draft", "id": "7630cc7a-8b17-5014-8138-4fdef4a806a7"}, {"name": "赵皋", "aliases": ["趙皋", "趙臯"], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "北汉忻州刺史。954年四月癸酉被监军李勍杀死。生年未载。", "biography": null, "status": "draft", "id": "827d0a54-569b-5a30-a5f9-d59873d0593b"}, {"name": "杨耨姑", "aliases": ["楊耨姑"], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "契丹通事。954年四月癸酉与北汉忻州刺史赵皋一同被李勍杀死。《旧五代史》称他为契丹大将，保留两书职务称谓。生年未载。", "biography": null, "status": "draft", "id": "a6147d22-9762-5299-be2a-c7040a50c94c"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "符彦卿奏报韩光愿以宪州投降后周", "start_year": 954, "end_year": 954, "time_original": "954年四月辛酉奏报，实际归降日未载", "dynasty": "五代十国", "description": "符彦卿奏报韩光愿以宪州投降后周。", "phases": [], "location_name": "宪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "73f75ec9-d721-5918-bb23-8baf401d394d"}, {"title": "符彦卿奏报岚州刺史郭言以城投降后周", "start_year": 954, "end_year": 954, "time_original": "954年四月辛酉奏报，实际归降日未载", "dynasty": "五代十国", "description": "符彦卿奏报岚州刺史郭言以城投降后周。", "phases": [], "location_name": "岚州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6ea3fc49-cece-5296-8c32-b7a82fdb884f"}, {"title": "符彦卿之女此前嫁给李守贞之子李崇训", "start_year": null, "end_year": null, "time_original": "949年河中城陷以前，具体婚期未载", "dynasty": "五代十国", "description": "符彦卿之女此前嫁给李守贞之子李崇训。", "phases": [], "location_name": "未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2c67a189-a50f-5232-8648-d8aa8f9aca48"}, {"title": "河中城陷时，李崇训先杀弟妹，继而寻找符氏准备杀她", "start_year": 949, "end_year": 949, "time_original": "949年七月河中城陷时，954年本条回述", "dynasty": "五代十国", "description": "河中城陷时，李崇训先杀弟妹，继而寻找符氏准备杀她。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3b7502e9-6a8d-5398-84e0-cd11b084778f"}, {"title": "符氏藏在帷幕后逃过杀害，李崇训未找到她便自杀", "start_year": 949, "end_year": 949, "time_original": "949年七月河中城陷时的回述", "dynasty": "五代十国", "description": "符氏藏在帷幕后逃过杀害，李崇训未找到她便自杀。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c40ad077-af1e-53cc-80ec-b82e52e7f40f"}, {"title": "符氏坐堂上斥责乱兵，称父亲与郭威如兄弟，要求勿失礼", "start_year": 949, "end_year": 949, "time_original": "949年七月河中城陷后", "dynasty": "五代十国", "description": "符氏坐堂上斥责乱兵，称父亲与郭威如兄弟，要求勿失礼。", "phases": [], "location_name": "河中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "4a3bee4c-2b00-5041-9f6e-bc4b011f82f3"}, {"title": "郭威派人将符氏送回符彦卿处", "start_year": 949, "end_year": 949, "time_original": "949年河中城陷、符氏获免以后", "dynasty": "五代十国", "description": "郭威派人将符氏送回符彦卿处。", "phases": [], "location_name": "河中至符彦卿处", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b6f56b28-e50e-58eb-9458-381bd8db4364"}, {"title": "符氏感念郭威救助，拜他为养父", "start_year": null, "end_year": null, "time_original": "949年获救以后，具体认养日期未载", "dynasty": "五代十国", "description": "符氏感念郭威救助，拜他为养父。", "phases": [], "location_name": "未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f02d1d6c-d5d7-5048-8a2a-e14485310a1d"}, {"title": "柴荣镇守澶州时，郭威为他娶符氏", "start_year": null, "end_year": null, "time_original": "符氏949年获救以后、954年立后以前，柴荣镇澶州期间", "dynasty": "五代十国", "description": "柴荣镇守澶州时，郭威为他娶符氏。", "phases": [], "location_name": "澶州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d9388a36-3bd5-5903-8c9d-ea5fe826d478"}, {"titl